css:
.negosim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2f45;
    background: linear-gradient(180deg, #f6f4ef 0%, #efeae1 100%);
    border-radius: 18px;
}

.negosim-container * {
    box-sizing: border-box;
}

.negosim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #2b2f55 0%, #3b3f6e 55%, #4a3d6b 100%);
    color: #f4f1ea;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #3a3e64;
    box-shadow: 0 14px 36px rgba(43, 47, 85, 0.28);
}

.negosim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fbf8f1;
}

.negosim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0c27b;
    background: rgba(240, 194, 123, 0.14);
    border: 1px solid rgba(240, 194, 123, 0.36);
    padding: 5px 14px;
    border-radius: 999px;
}

.negosim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d8d4e6;
}

.negosim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a5f7a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.negosim-period-counter #currentDay,
.negosim-period-counter #maxPeriods {
    font-weight: 800;
    color: #c4791f;
}

.negosim-round-name {
    background: rgba(196, 121, 31, 0.12);
    color: #b06a17;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.negosim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a3d3d;
    background: rgba(176, 70, 70, 0.10);
    border: 1px solid rgba(176, 70, 70, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.negosim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.negosim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3dccf;
    box-shadow: 0 6px 16px rgba(43, 47, 85, 0.08);
    border-top: 4px solid #6b6f9c;
}

.negosim-card-agreement { border-top-color: #3f7d6e; }
.negosim-card-relationship { border-top-color: #4a73b8; }
.negosim-card-innovation { border-top-color: #8a5cb8; }
.negosim-card-time { border-top-color: #c4791f; }

.negosim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a7f99;
}

.negosim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2a2f45;
    font-variant-numeric: tabular-nums;
}

.negosim-card-agreement .negosim-value { color: #2f6d5e; }
.negosim-card-relationship .negosim-value { color: #3a63a8; }
.negosim-card-innovation .negosim-value { color: #784fa8; }
.negosim-card-time .negosim-value { color: #b06a17; }

.negosim-sublabel {
    font-size: 0.76rem;
    color: #8a8fa6;
    line-height: 1.35;
}

.negosim-relationship-strong { border-top-color: #2f9e6e; }
.negosim-relationship-strong .negosim-value { color: #1f8c5c; }
.negosim-relationship-weak { border-top-color: #d4423a; }
.negosim-relationship-weak .negosim-value { color: #c43229; }

.negosim-time-over { border-top-color: #d4423a; }
.negosim-time-over .negosim-value { color: #c43229; }

.negosim-dial-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fbf6ec;
    border: 1px solid #e6d8bf;
    color: #5a4a2a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.negosim-dial-bar #dialDisplay {
    font-size: 1rem;
    letter-spacing: 0.2px;
    color: #b06a17;
}

.negosim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c4791f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(43, 47, 85, 0.08);
}

.negosim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.negosim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2a2f45;
    margin-bottom: 6px;
}

.negosim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4f68;
}

.negosim-briefing-text strong { color: #2f6d5e; }
.negosim-briefing-text em { color: #b06a17; font-style: italic; }

.negosim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dccf;
    box-shadow: 0 6px 16px rgba(43, 47, 85, 0.08);
}

.negosim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2a2f45;
    border-bottom: 2px solid #ece6da;
    padding-bottom: 8px;
}

.negosim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3f58;
    margin: 14px 0 6px;
}

.negosim-container select,
.negosim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d4cdbd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf9f4;
    color: #2a2f45;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.negosim-container select:focus,
.negosim-container input[type="number"]:focus {
    outline: none;
    border-color: #c4791f;
    box-shadow: 0 0 0 3px rgba(196, 121, 31, 0.16);
}

.negosim-container select option {
    background-color: #ffffff;
    color: #2a2f45;
}

.negosim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c4791f;
}

.negosim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a5f7a;
    margin-top: 4px;
}

.negosim-range-readout span:last-child {
    color: #b06a17;
    font-weight: 800;
}

.negosim-hint {
    font-size: 0.8rem;
    color: #8a8fa6;
    margin-top: 4px;
    line-height: 1.4;
}

.negosim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.negosim-container .btn-primary {
    background: linear-gradient(135deg, #2f6d5e 0%, #3f9e7e 100%);
    border: none;
    color: #f4fff9;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(47, 109, 94, 0.30);
}

.negosim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.negosim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d4cdbd;
    color: #6a6f88;
    background: transparent;
}

.negosim-coach {
    background: linear-gradient(160deg, #2b2f55 0%, #36305a 100%);
    color: #e6e2f0;
    border: 1px solid #3a3e64;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(43, 47, 85, 0.20);
}

.negosim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0c27b;
    margin-bottom: 8px;
}

.negosim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.negosim-coach-body strong { color: #f0c27b; }
.negosim-coach-body em { color: #9bd0c0; font-style: italic; }

.negosim-history,
.negosim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dccf;
    box-shadow: 0 6px 16px rgba(43, 47, 85, 0.08);
}

.negosim-history h3,
.negosim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2a2f45;
}

.negosim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a3f58;
}

.negosim-container table#usfHistoryTable th {
    background: #f3eee4;
    color: #b06a17;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e3dccf;
}

.negosim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece6da;
    color: #4a4f68;
}

.negosim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f1;
}

.negosim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .negosim-container {
        padding: 14px;
    }
    .negosim-header h1 {
        font-size: 1.7rem;
    }
    .negosim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .negosim-value {
        font-size: 2rem;
    }
    .negosim-clock {
        margin-left: 0;
    }
    .negosim-period-counter {
        font-size: 0.88rem;
    }
    .negosim-dial-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .negosim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}



/* \u2500\u2500 v1.1.0 completion scorecard (append-only, namespaced .nego-cm-*, negotiation indigo/violet/amber) \u2500\u2500 */
.nego-cm { margin-top: 8px; }
.nego-cm-incomplete { text-align: center; color: #4c4f6b; font-size: 1rem; padding: 18px; }
.nego-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.nego-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #2c2f5a 0%, #4b4f9c 55%, #d99a2b 135%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(44, 47, 90, 0.28); }
.nego-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.nego-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.nego-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f0d29a; }
.nego-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #ffffff; border: 1px solid #dcdcec; border-left: 5px solid #4b4f9c; border-radius: 14px; padding: 16px 20px; }
.nego-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5c5f74; }
.nego-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #2c2f5a; line-height: 1.15; }
.nego-cm-section { margin-bottom: 16px; }
.nego-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5c5f74; margin-bottom: 8px; }
.nego-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.nego-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.nego-cm-ok { background: rgba(31, 157, 85, 0.14); color: #1f9d55; border-color: rgba(31, 157, 85, 0.42); }
.nego-cm-no { background: rgba(214, 69, 69, 0.12); color: #d64545; border-color: rgba(214, 69, 69, 0.42); }
.nego-cm-ico { font-weight: 800; }
.nego-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.nego-cm-kpi { background: #ffffff; border: 1px solid #dcdcec; border-top: 4px solid #d99a2b; border-radius: 12px; padding: 14px 12px; text-align: center; }
.nego-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #2c2f5a; line-height: 1; }
.nego-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #23263a; }
.nego-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #5c5f74; }
.nego-cm-insights { margin: 0; padding-left: 18px; color: #23263a; }
.nego-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .nego-cm-head { flex-direction: column; } .nego-cm-score { min-width: 0; } }

