(function() {
    'use strict';

    class NegotiatorAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Confident Negotiator`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Nimbus Systems Pvt. Ltd.).
            this.SHARED_ENGINEERS = 9;       // the literal point of contention
            this.ANCHOR_CONTRACT = 88;       // INR 88 crore/year largest anchor
            this.EXPANSION = 22;             // INR 22 crore expansion bookings at risk
            this.ATTRITION = 45;             // ~INR 45 lakh per senior replacement
            this.MEETING_MINUTES = 75;       // one 75-min session — the hard constraint
            this.INFLECTION = 60;            // confidence paradox inflection point (0-100)

            // Concept truths (the calibrated, integrative path).
            this.TRUE_INTEREST = `stability`;
            this.TRUE_OWN = `booking`;
            this.TRUE_MODE = `collaborating`;
            this.TRUE_MOVE = `interests`;
            this.TRUE_OPTION = `phased`;
        }

        // Inverted-U confidence paradox: peak value at the inflection point,
        // falling off on both sides. Returns roughly -1..+1.
        _confidenceCurve(dial) {
            const d = Math.max(0, Math.min(100, dial));
            // Parabola peaking at INFLECTION, normalised so peak = 1, edges ~ -0.8.
            const spread = 40; // controls how sharply confidence over/under-shoots bite
            const val = 1 - Math.pow((d - this.INFLECTION) / spread, 2);
            return Math.max(-1, val);
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    agreement: 25,           // agreement quality (specific & operationalisable)
                    relationship: 50,        // relationship strength / talent retention
                    innovation: 20,          // integrative value created
                    minutesUsed: 0,          // minutes consumed of the 75-min session
                    departures: 0,           // senior departures triggered (PM / engineer)
                    surfacedInterests: false,
                    vagueDeal: false,
                    agreementHistory: [25],
                    relationshipHistory: [50],
                    innovationHistory: [20],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    interest: `position`,
                    ownInterest: `ego`,
                    dial: 55,
                    mode: `competing`,
                    fallback: `competing`,
                    recalibrate: 55,
                    opening: `match`,
                    move: `positions`,
                    option: `moduleonly`,
                    engineers: 3,
                    pressure: `cave`,
                    customer: `generic`,
                    allocation: `verbal`,
                    repair: `private`,
                    finalConf: 55
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ai = document.getElementById(`interestInput`);
                const oi = document.getElementById(`ownInterestInput`);
                const di = document.getElementById(`dialInput`);
                if (ai) decisions.interest = ai.value;
                if (oi) decisions.ownInterest = oi.value;
                if (di) decisions.dial = parseInt(di.value, 10);
                if (!Number.isFinite(decisions.dial) || decisions.dial < 0 || decisions.dial > 100) {
                    warn(`warn_dial_range`); return false;
                }
            } else if (round === 2) {
                const md = document.getElementById(`modeInput`);
                const fb = document.getElementById(`fallbackInput`);
                const rc = document.getElementById(`recalibrateInput`);
                const op = document.getElementById(`openingInput`);
                if (md) decisions.mode = md.value;
                if (fb) decisions.fallback = fb.value;
                if (rc) decisions.recalibrate = parseInt(rc.value, 10);
                if (op) decisions.opening = op.value;
                if (!Number.isFinite(decisions.recalibrate) || decisions.recalibrate < 0 || decisions.recalibrate > 100) {
                    warn(`warn_recalibrate_range`); return false;
                }
            } else if (round === 3) {
                const mv = document.getElementById(`moveInput`);
                const op = document.getElementById(`optionInput`);
                const en = document.getElementById(`engineersInput`);
                const pr = document.getElementById(`pressureInput`);
                if (mv) decisions.move = mv.value;
                if (op) decisions.option = op.value;
                if (en) decisions.engineers = parseInt(en.value, 10);
                if (pr) decisions.pressure = pr.value;
                if (!Number.isFinite(decisions.engineers) || decisions.engineers < 0 || decisions.engineers > this.SHARED_ENGINEERS) {
                    warn(`warn_engineers_range`); return false;
                }
            } else if (round === 4) {
                const cu = document.getElementById(`customerInput`);
                const al = document.getElementById(`allocationInput`);
                const rp = document.getElementById(`repairInput`);
                const fc = document.getElementById(`finalConfInput`);
                if (cu) decisions.customer = cu.value;
                if (al) decisions.allocation = al.value;
                if (rp) decisions.repair = rp.value;
                if (fc) decisions.finalConf = parseInt(fc.value, 10);
                if (!Number.isFinite(decisions.finalConf) || decisions.finalConf < 0 || decisions.finalConf > 100) {
                    warn(`warn_finalconf_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let agreementDelta = 0, relationshipDelta = 0, innovationDelta = 0, minutes = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the deadlock and your own confidence. (Common Error 3: positions.)
                minutes = 15;
                switch (d.interest) {
                    case `stability`: innovationDelta += 10; agreementDelta += 5; relationshipDelta += 4; ds.surfacedInterests = true; coachKey = `coach_r1_stability`; break;
                    case `power`: relationshipDelta -= 4; innovationDelta -= 3; coachKey = `coach_r1_power`; break;
                    case `budget`: innovationDelta -= 3; coachKey = `coach_r1_budget`; break;
                    case `position`: innovationDelta -= 5; coachKey = `coach_r1_position`; break;
                }
                switch (d.ownInterest) {
                    case `booking`: agreementDelta += 6; innovationDelta += 4; break;
                    case `ego`: relationshipDelta -= 5; innovationDelta -= 4; coachKey = `coach_r1_ego`; break;
                    case `feature`: innovationDelta -= 2; break;
                }

                // Confidence paradox (inverted-U). Calibrated near 60 helps everything;
                // too high hardens the counterpart, too low forfeits the case.
                const c = this._confidenceCurve(d.dial);
                relationshipDelta += Math.round(c * 6);
                innovationDelta += Math.round(c * 5);
                if (d.dial >= 85) { relationshipDelta -= 6; coachKey = `coach_r1_overconfident`; }
                else if (d.dial <= 25) { agreementDelta -= 6; coachKey = `coach_r1_underconfident`; }
                else if (d.interest === `stability` && d.ownInterest === `booking`) { coachKey = `coach_r1_sharp`; }

                summaryKey = (d.interest === `stability` && d.ownInterest === `booking`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Calibrate confidence & choose a conflict mode. (Common Errors 1 & 2.)
                minutes = 18;
                switch (d.mode) {
                    case `collaborating`: innovationDelta += 12; agreementDelta += 6; relationshipDelta += 6; coachKey = `coach_r2_collaborating`; break;
                    case `competing`: agreementDelta += 5; relationshipDelta -= 8; innovationDelta -= 6; coachKey = `coach_r2_competing`; break;
                    case `compromising`: agreementDelta += 4; innovationDelta -= 2; coachKey = `coach_r2_compromising`; break;
                    case `avoiding`: agreementDelta -= 8; relationshipDelta -= 2; coachKey = `coach_r2_avoiding`; break;
                    case `accommodating`: agreementDelta -= 6; relationshipDelta += 3; innovationDelta -= 4; coachKey = `coach_r2_accommodating`; break;
                }
                // A deliberate fallback (the discipline of switching modes) is rewarded.
                switch (d.fallback) {
                    case `collaborating`: innovationDelta += 4; agreementDelta += 2; break;
                    case `compromising`: agreementDelta += 3; break;
                    case `competing`: relationshipDelta -= 4; break;
                    case `none`: agreementDelta -= 3; innovationDelta -= 3; coachKey = (d.mode === `collaborating`) ? `coach_r2_nofallback` : coachKey; break;
                }

                // Re-calibrated confidence — inverted-U again.
                const c = this._confidenceCurve(d.recalibrate);
                relationshipDelta += Math.round(c * 6);
                innovationDelta += Math.round(c * 5);
                if (d.recalibrate >= 85) { relationshipDelta -= 7; if (coachKey === `coach_default` || coachKey === `coach_r2_collaborating`) coachKey = `coach_r2_overconfident`; }
                else if (d.recalibrate <= 25) { agreementDelta -= 6; }

                switch (d.opening) {
                    case `acknowledge`: relationshipDelta += 6; innovationDelta += 5; agreementDelta += 3; break;
                    case `match`: relationshipDelta -= 5; coachKey = (d.mode === `competing`) ? `coach_r2_matchforce` : coachKey; break;
                    case `retreat`: agreementDelta -= 5; relationshipDelta -= 2; break;
                }

                summaryKey = (d.mode === `collaborating` && d.opening === `acknowledge`) ? `sum_r2_good` :
                             (d.mode === `competing` ? `sum_r2_competing` :
                             ((d.mode === `accommodating` || d.mode === `avoiding`) ? `sum_r2_yielded` : `sum_r2_weak`));
            } else if (round === 3) {
                // Structure & run the live negotiation. (Common Errors 3 & 4.)
                minutes = 25;
                switch (d.move) {
                    case `interests`: innovationDelta += 12; agreementDelta += 6; relationshipDelta += 5; ds.surfacedInterests = true; coachKey = `coach_r3_interests`; break;
                    case `positions`: innovationDelta -= 8; relationshipDelta -= 4; coachKey = `coach_r3_positions`; break;
                    case `split`: innovationDelta -= 5; agreementDelta += 2; coachKey = `coach_r3_split`; break;
                }
                switch (d.option) {
                    case `phased`: innovationDelta += 14; agreementDelta += 10; relationshipDelta += 4; break;
                    case `moduleonly`: agreementDelta += 4; relationshipDelta -= 8; innovationDelta -= 4; coachKey = `coach_r3_moduleonly`; break;
                    case `rearchonly`: agreementDelta += 2; innovationDelta -= 6; coachKey = `coach_r3_rearchonly`; break;
                    case `vague`: agreementDelta -= 12; innovationDelta -= 6; ds.vagueDeal = true; coachKey = `coach_r3_vague`; break;
                }

                // Engineer allocation: integrative band ≈ 3–5 on hardening de-risks the module.
                const e = d.engineers;
                if (d.option === `phased`) {
                    if (e >= 3 && e <= 5) { innovationDelta += 6; agreementDelta += 4; }
                    else if (e <= 1) { innovationDelta -= 6; coachKey = `coach_r3_starved`; }
                    else if (e >= 8) { agreementDelta -= 5; innovationDelta -= 4; coachKey = `coach_r3_overloaded`; }
                    else { innovationDelta += 2; }
                }

                // CEO pushes for speed. Holding the process costs a little time but protects depth.
                switch (d.pressure) {
                    case `hold`: minutes += 4; innovationDelta += 5; agreementDelta += 4; relationshipDelta += 2; break;
                    case `cave`: minutes -= 8; agreementDelta -= 6; innovationDelta -= 5; coachKey = `coach_r3_cave`; break;
                    case `escalate`: minutes -= 6; agreementDelta -= 10; relationshipDelta -= 6; innovationDelta -= 6; coachKey = `coach_r3_escalate`; break;
                }

                summaryKey = (d.move === `interests` && d.option === `phased`) ? `sum_r3_good` :
                             (d.option === `vague` ? `sum_r3_vague` :
                             (d.pressure === `escalate` ? `sum_r3_escalated` : `sum_r3_weak`));
            } else if (round === 4) {
                // Lock the deal & protect the relationship. (Common Errors 4 & 5.)
                minutes = 13;
                switch (d.customer) {
                    case `specific`: agreementDelta += 12; innovationDelta += 3; break;
                    case `generic`: agreementDelta -= 4; coachKey = `coach_r4_generic`; break;
                    case `none`: agreementDelta -= 8; coachKey = `coach_r4_nocustomer`; break;
                }
                switch (d.allocation) {
                    case `documented`: agreementDelta += 12; relationshipDelta += 4; break;
                    case `verbal`: agreementDelta -= 8; ds.vagueDeal = true; coachKey = `coach_r4_verbal`; break;
                    case `open`: agreementDelta -= 12; ds.vagueDeal = true; coachKey = `coach_r4_open`; break;
                }
                // Relationship repair — does the at-risk PM and engineer stay?
                switch (d.repair) {
                    case `joint`: relationshipDelta += 14; innovationDelta += 5; coachKey = `coach_r4_joint`; break;
                    case `private`: relationshipDelta += 4; break;
                    case `ignore`: relationshipDelta -= 12; coachKey = `coach_r4_ignore`; break;
                }

                // Final confidence — inverted-U one last time.
                const c = this._confidenceCurve(d.finalConf);
                relationshipDelta += Math.round(c * 5);
                if (d.finalConf >= 85) relationshipDelta -= 5;
                else if (d.finalConf <= 25) agreementDelta -= 4;

                summaryKey = (d.customer === `specific` && d.allocation === `documented` && d.repair === `joint`) ? `sum_r4_good` :
                             (d.repair === `ignore` ? `sum_r4_ignored` :
                             ((d.allocation === `verbal` || d.allocation === `open`) ? `sum_r4_vague` : `sum_r4_weak`));
            }

            // Time accounting.
            ds.minutesUsed = Math.max(0, ds.minutesUsed + minutes);

            // Apply deltas, clamped 0-100.
            ds.agreement = Math.max(0, Math.min(100, Math.round(ds.agreement + agreementDelta)));
            ds.relationship = Math.max(0, Math.min(100, Math.round(ds.relationship + relationshipDelta)));
            ds.innovation = Math.max(0, Math.min(100, Math.round(ds.innovation + innovationDelta)));

            // Attrition: a collapsed relationship loses the at-risk senior talent.
            ds.departures = 0;
            if (ds.relationship < 35) ds.departures = 1;
            if (ds.relationship < 20) ds.departures = 2;

            ds.agreementHistory.push(ds.agreement);
            ds.relationshipHistory.push(ds.relationship);
            ds.innovationHistory.push(ds.innovation);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook actually reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                agreement: ds.agreement,
                agreementDelta: Math.round(agreementDelta),
                relationship: ds.relationship,
                relationshipDelta: Math.round(relationshipDelta),
                innovation: ds.innovation,
                innovationDelta: Math.round(innovationDelta),
                minutesUsed: ds.minutesUsed,
                departures: ds.departures,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

