        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const agreement = Math.round(ds.agreement);
            const relationship = Math.round(ds.relationship);
            const innovation = Math.round(ds.innovation);
            const minutes = Math.round(ds.minutesUsed);
            const departures = ds.departures;
            let timeScore;
            if (minutes >= 55 && minutes <= this.MEETING_MINUTES + 3) timeScore = 100;
            else if (minutes < 55) timeScore = Math.max(35, 100 - (55 - minutes) * 4);
            else timeScore = Math.max(30, 100 - (minutes - (this.MEETING_MINUTES + 3)) * 5);
            let composite = Math.round(
                agreement * 0.30 + relationship * 0.30 + innovation * 0.28 + timeScore * 0.12
            );
            return Math.max(0, composite - departures * 12);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const agreement = Math.round(ds.agreement);
            const relationship = Math.round(ds.relationship);
            const innovation = Math.round(ds.innovation);
            const minutes = Math.round(ds.minutesUsed);
            const departures = ds.departures;

            // Time KPI as a 0-100 score: best when used efficiently but not rushed.
            // Target band ≈ 55-78 minutes; rushing (too few) or overrunning both cost.
            let timeScore;
            if (minutes >= 55 && minutes <= this.MEETING_MINUTES + 3) timeScore = 100;
            else if (minutes < 55) timeScore = Math.max(35, 100 - (55 - minutes) * 4); // rushed = shallow
            else timeScore = Math.max(30, 100 - (minutes - (this.MEETING_MINUTES + 3)) * 5); // overran the session

            // Composite extracted to _composite() so the persisted per-period score and this
            // completion summary are identical by construction (v1.1.0).
            const composite = this._composite(ds);

            const operational = agreement >= 60 && !ds.vagueDeal;
            const relationshipHeld = relationship >= 60 && departures === 0;
            const innovative = innovation >= 60;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_deadlock`;
            if (operational && relationshipHeld && innovative && composite >= 78) tierKey = `grade_integrative`;
            else if (operational && relationshipHeld) tierKey = `grade_dealheld`;
            else if (departures >= 1 && agreement >= 60) tierKey = `grade_wonlost`;
            else if (ds.vagueDeal) tierKey = `grade_handshake`;
            else if (relationship < 35) tierKey = `grade_broken`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (operational && relationshipHeld && innovative) insights.push(window.mySimulation.t(`insight_integrative`));
            else if (departures >= 1 && agreement >= 60) insights.push(window.mySimulation.t(`insight_won_lost`));
            else if (ds.vagueDeal) insights.push(window.mySimulation.t(`insight_vague`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (departures >= 1) insights.push(window.mySimulation.t(`insight_attrition`));
            if (!ds.surfacedInterests) insights.push(window.mySimulation.t(`insight_positions`));
            if (innovation < 45) insights.push(window.mySimulation.t(`insight_lowinnovation`));
            if (minutes < 50) insights.push(window.mySimulation.t(`insight_rushed`));
            if (operational && relationshipHeld && innovative) insights.push(window.mySimulation.t(`insight_paradox`));

            return {
                agreement: agreement,
                relationship: relationship,
                innovation: innovation,
                minutes: minutes,
                departures: departures,
                timeScore: Math.round(timeScore),
                operational: operational,
                relationshipHeld: relationshipHeld,
                innovative: innovative,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                timeManaged: (minutes >= 55 && minutes <= this.MEETING_MINUTES + 3),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="nego-cm"><p class="nego-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="nego-cm-chip ` + (ok ? `nego-cm-ok` : `nego-cm-no`) + `">` +
